fn bio_op(bio: *const bio) -> u32 {
((unsafe { (*bio).bi_opf }) & 255u32) as u32
}

fn op_is_write(op: u32) -> bool {
op & 1 != 0
}

fn op_is_discard(op: u32) -> bool {
op & 255u32 == 3
}

fn op_stat_group(op: u32) -> i32 {
if op_is_discard(op as u32) {
return 2;
}
op_is_write(op as u32) as i32
}

