fn add_disk(disk: *mut gendisk) -> i32 {
unsafe { device_add_disk(core::ptr::null_mut::<device>(), disk, core::ptr::null_mut::<*const attribute_group>()) }
}

fn bdev_partno(bdev: *const block_device) -> u8 {
(atomic_read(unsafe { core::ptr::addr_of!((*bdev).__bd_flags) }) & 255) as u8
}

fn bdev_test_flag(bdev: *const block_device, flag: u32) -> bool {
(atomic_read(unsafe { core::ptr::addr_of!((*bdev).__bd_flags) }) as u32) & flag != 0
}

fn get_disk_ro(disk: *mut gendisk) -> bool {
bdev_test_flag((unsafe { (*disk).part0 }) as *const block_device, 256u32) || test_bit!(1i32, unsafe { core::ptr::addr_of_mut!((*disk).state) }) != 0
}

fn bdev_read_only(bdev: *mut block_device) -> bool {
bdev_test_flag(bdev as *const block_device, 256u32) || get_disk_ro(unsafe { (*bdev).bd_disk })
}

fn bdev_nr_sectors(bdev: *mut block_device) -> u64 {
unsafe { (*bdev).bd_nr_sectors }
}

fn bdev_nr_bytes(bdev: *mut block_device) -> i64 {
(bdev_nr_sectors(bdev) as i64) << 9i32
}

// blk_alloc_disk - allocate a gendisk structure
// @lim: queue limits to be used for this disk.
// @node_id: numa node to allocate on
//
// Allocate and pre-initialize a gendisk structure for use with BIO based
// drivers.
//
// Returns an ERR_PTR on error, else the allocated disk.
//
// Context: can sleep
fn bdev_get_queue(bdev: *mut block_device) -> *mut request_queue {
return unsafe { (*bdev).bd_queue }; // this is never NULL
}

fn queue_limits_start_update(q: *mut request_queue) -> queue_limits {
unsafe { mutex_lock(core::ptr::addr_of_mut!((*q).limits_lock)) };
return unsafe { (*q).limits };
}

fn queue_limits_cancel_update(q: *mut request_queue) {
unsafe { mutex_unlock(core::ptr::addr_of_mut!((*q).limits_lock)) };
}

fn bdev_is_partition(bdev: *mut block_device) -> bool {
(bdev_partno(bdev as *const block_device) as i32) != 0
}

fn bdev_limits(bdev: *mut block_device) -> *mut queue_limits {
unsafe { core::ptr::addr_of_mut!((*bdev_get_queue(bdev)).limits) }
}

fn queue_logical_block_size(q: *const request_queue) -> u32 {
unsafe { (*q).limits.logical_block_size }
}

fn bdev_logical_block_size(bdev: *mut block_device) -> u32 {
queue_logical_block_size(bdev_get_queue(bdev) as *const request_queue)
}

fn bdev_max_discard_sectors(bdev: *mut block_device) -> u32 {
unsafe { (*bdev_limits(bdev)).max_discard_sectors }
}

